spec.setup_code:
function cl(x){return x<0?0:x>1?1:x;}
function sm(x){x=cl(x);return x*x*(3-2*x);}
function hs(n){n=Math.sin(n*127.1+311.7)*43758.5453;return n-Math.floor(n);}
var N=25,TG=[],i0;
for(i0=0;i0<N;i0++){var a0=i0*0.62,r0=0.55+0.22*Math.sin(i0*0.5);TG.push([Math.cos(a0)*r0,(i0/24-0.5)*1.5+0.12*Math.sin(a0*1.3),Math.sin(a0)*r0]);}
var INK='#04204B',SEC='#3D5F91',GUIDE='#8098BC',BLUE='#0B4FC0',WARM='#B4552F';
var PER=14;

function cloud(ctx,cx,cy,S,sig,step,sid,rot,al,dr,lw){
  var P=[],i,k,cr=Math.cos(rot),sr=Math.sin(rot);
  for(i=0;i<N;i++){
    var q=[];
    for(k=0;k<3;k++){
      var tg=TG[i][k]+(hs(i*7.1+sid*13.3+k*3.7)-0.5)*0.25;
      var nz=(hs(i*3.1+sid*17.3+k*5.9+50)-0.5)*2.4;
      var jt=(hs(i*5.3+step*1.7+sid*3+k*9.1)-0.5)*0.4*sig;
      q.push(tg+(nz-tg)*sig+jt);
    }
    var x=q[0]*cr+q[2]*sr,z=-q[0]*sr+q[2]*cr;
    var f=1/(1-z*0.2);
    P.push([cx+x*S*f,cy+q[1]*S*f,f]);
  }
  ctx.globalAlpha=al;
  ctx.strokeStyle=SEC;ctx.lineWidth=lw;
  ctx.beginPath();
  for(i=0;i<N;i++){if(i===0)ctx.moveTo(P[i][0],P[i][1]);else ctx.lineTo(P[i][0],P[i][1]);}
  ctx.globalAlpha=al*0.6;ctx.stroke();
  ctx.globalAlpha=al;
  var cr2=Math.round(11+(128-11)*sig),cg=Math.round(79+(152-79)*sig),cb=Math.round(192+(188-192)*sig);
  ctx.fillStyle='rgb('+cr2+','+cg+','+cb+')';
  for(i=0;i<N;i++){ctx.beginPath();ctx.arc(P[i][0],P[i][1],dr*P[i][2],0,6.2832);ctx.fill();}
  ctx.globalAlpha=1;
}

function arrow(ctx,x1,y1,x2,y2,col,lw){
  var dx=x2-x1,dy=y2-y1,L=Math.sqrt(dx*dx+dy*dy)||1,ux=dx/L,uy=dy/L;
  ctx.strokeStyle=col;ctx.fillStyle=col;ctx.lineWidth=lw;
  ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2-ux*5,y2-uy*5);ctx.stroke();
  ctx.beginPath();ctx.moveTo(x2,y2);ctx.lineTo(x2-ux*7-uy*3.5,y2-uy*7+ux*3.5);ctx.lineTo(x2-ux*7+uy*3.5,y2-uy*7-ux*3.5);ctx.closePath();ctx.fill();
}

function loopArrow(ctx,cx,cy,r,a0,col,lw){
  var a1=a0+4.4;
  ctx.strokeStyle=col;ctx.fillStyle=col;ctx.lineWidth=lw;
  ctx.beginPath();ctx.arc(cx,cy,r,a0,a1);ctx.stroke();
  var ex=cx+r*Math.cos(a1),ey=cy+r*Math.sin(a1),tx=-Math.sin(a1),ty=Math.cos(a1),nx=Math.cos(a1),ny=Math.sin(a1);
  ctx.beginPath();ctx.moveTo(ex+tx*5,ey+ty*5);ctx.lineTo(ex+nx*3.5,ey+ny*3.5);ctx.lineTo(ex-nx*3.5,ey-ny*3.5);ctx.closePath();ctx.fill();
}

function pathPt(pts,f){
  var L=[],tot=0,i;
  for(i=1;i<pts.length;i++){var d=Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]);L.push(d);tot+=d;}
  var s=f*tot;
  for(i=0;i<L.length;i++){
    if(s<=L[i]||i===L.length-1){var u=cl(s/(L[i]||1));return [pts[i][0]+(pts[i+1][0]-pts[i][0])*u,pts[i][1]+(pts[i+1][1]-pts[i][1])*u];}
    s-=L[i];
  }
  return pts[0];
}

return {draw:function(ctx,W,H,time,dt){
  ctx.fillStyle='#ffffff';ctx.fillRect(0,0,W,H);
  var t=time%PER;
  var fs=W<500?11:12;
  ctx.textBaseline='middle';
  function txt(s,x,y,col,al,maxW,bold){
    var sz=fs;
    ctx.font=(bold?'bold ':'')+sz+'px sans-serif';
    while(maxW&&sz>11&&ctx.measureText(s).width>maxW){sz--;ctx.font=(bold?'bold ':'')+sz+'px sans-serif';}
    ctx.fillStyle=col;ctx.globalAlpha=al;ctx.fillText(s,x,y);ctx.globalAlpha=1;
  }
  // timeline
  var u3=cl((t-4.6)/3.8),u4=cl((t-9.2)/3.4);
  var uMain=t<8.8?u3:u4;
  var mainA=t<8.4?1:(t<8.8?1-(t-8.4)/0.4:(t<9.2?(t-8.8)/0.4:1));
  var minisA=t<8.6?0:Math.min(1,(t-8.6)/0.5);
  var endF=t<12.6?1:Math.max(0,1-(t-12.6)/0.4);
  var flowA=(t<4.6?0:Math.min(1,(t-4.6)/0.3))*endF;
  var busA=sm((t-8.6)/0.5)*endF;
  var sigM=Math.pow(1-uMain,2),sigS=Math.pow(1-u4,2);
  var stepMain=Math.floor(200*uMain),stepS=Math.floor(200*u4);

  // layout
  var tx=0.03*W,tw=0.25*W,ty=0.11*H,th=0.69*H,tcx=tx+tw/2;
  var bx=0.55*W,bw=0.42*W,by=0.11*H,bh=0.41*H;
  var pw=Math.max(58,Math.min(70,0.17*W)),ph=22,pcx=tx+tw+(bx-tx-tw)/2,pcy=0.25*H;

  // caption
  var cap,capT;
  if(t<3.6){cap='Trunk runs once, recycling 4 times';capT=0;}
  else if(t<4.6){cap='Trunk emits conditioning c = (s, z)';capT=3.6;}
  else if(t<8.4){cap='Denoiser loops 200 steps, reading c each step';capT=4.6;}
  else{cap='5 samples in parallel, same c, no trunk re-run';capT=8.4;}
  ctx.textAlign='center';
  txt(cap,W/2,18,INK,Math.min(1,0.3+(t-capT)/0.3),W-16,true);

  // trunk
  ctx.fillStyle=INK;ctx.fillRect(tx,ty,tw,th);
  var cyc=Math.min(3,Math.floor(t/0.9)),p=t<3.6?sm((t%0.9)/0.8):1;
  var ih=th-10;
  ctx.fillStyle=BLUE;ctx.globalAlpha=0.9;ctx.fillRect(tx+5,ty+th-5-p*ih,tw-10,p*ih);
  ctx.globalAlpha=0.14;ctx.strokeStyle='#ffffff';ctx.lineWidth=1;
  var b;
  for(b=1;b<12;b++){ctx.beginPath();ctx.moveTo(tx+5,ty+5+b*ih/12);ctx.lineTo(tx+tw-5,ty+5+b*ih/12);ctx.stroke();}
  ctx.globalAlpha=1;
  ctx.textAlign='center';
  txt('trunk',tcx,ty+17,'#ffffff',1,tw-8,true);
  txt('(Pairformer,',tcx,ty+33,'#ffffff',1,tw-8);
  txt('48–64 blocks)',tcx,ty+48,'#ffffff',1,tw-8);
  loopArrow(ctx,tcx,ty+th*0.5,11,t<3.6?time*5:0.8,'#ffffff',2);
  txt('recycle '+(cyc+1)+' / 4',tcx,ty+th*0.5+26,'#ffffff',1,tw-8);
  txt(t<3.6?'block fill':'done',tcx,ty+th*0.5+42,'#ffffff',0.8,tw-8);
  // inputs
  var iy0=0.86*H;
  arrow(ctx,tcx,iy0,tcx,ty+th+1,INK,1.5);
  if(t<3.6){
    ctx.fillStyle=BLUE;
    for(b=0;b<3;b++){var f=((t/0.6)+b/3)%1;ctx.beginPath();ctx.arc(tcx,iy0+(ty+th-iy0)*f,2.5,0,6.2832);ctx.fill();}
  }
  txt('sequence + MSA',tcx,0.91*H,INK,1,tw+30);
  txt('+ templates',tcx,0.96*H,INK,1,tw+30);

  // pill c
  var ps=sm((t-3.6)/0.6);
  ctx.strokeStyle=WARM;ctx.lineWidth=1;ctx.globalAlpha=0.3*(1-ps);
  ctx.strokeRect(pcx-pw/2,pcy-ph/2,pw,ph);ctx.globalAlpha=1;
  if(ps>0){
    var hw=pw*ps/2,hh=ph*ps/2,rr=hh;
    ctx.fillStyle=WARM;ctx.beginPath();
    ctx.moveTo(pcx-hw+rr,pcy-hh);ctx.lineTo(pcx+hw-rr,pcy-hh);ctx.arc(pcx+hw-rr,pcy,rr,-1.5708,1.5708);
    ctx.lineTo(pcx-hw+rr,pcy+hh);ctx.arc(pcx-hw+rr,pcy,rr,1.5708,4.7124);ctx.fill();
    if(ps>0.8)txt('c = (s, z)',pcx,pcy,'#ffffff',1,pw-8,true);
    var ea=sm((t-3.7)/0.4);
    ctx.globalAlpha=ea;arrow(ctx,tx+tw,pcy,pcx-pw/2-1,pcy,INK,1.5);ctx.globalAlpha=1;
  }

  // denoiser box
  ctx.fillStyle='#F4F7FC';ctx.fillRect(bx,by,bw,bh);
  ctx.strokeStyle=INK;ctx.lineWidth=1.8;ctx.strokeRect(bx,by,bw,bh);
  ctx.textAlign='center';
  txt('denoiser D_θ(x, σ | c)',bx+bw/2,by+15,INK,1,bw-8,true);
  var S1=Math.min(bw*0.2,bh*0.24);
  cloud(ctx,bx+bw/2,by+bh*0.47,S1,sigM,stepMain,0,time*0.5,mainA*(t<4.6?0.65:1),3,1.3);
  ctx.textAlign='left';
  txt('step '+stepMain+' / 200',bx+8,by+bh-22,INK,1,bw-40);
  txt('σ = '+(16*(0.02+160*sigM)).toFixed(0)+' Å'+(t>=8.4?'  ×5':''),bx+8,by+bh-8,SEC,1,bw-40);
  var running=(t>=4.6&&t<8.4)||(t>=9.2&&t<12.6);
  loopArrow(ctx,bx+bw-18,by+bh-18,8,running?time*6:0.5,BLUE,1.8);

  // c flow into denoiser (dashed warm)
  if(flowA>0){
    ctx.globalAlpha=flowA;ctx.setLineDash([4,3]);ctx.lineDashOffset=-time*30;
    ctx.strokeStyle=WARM;ctx.lineWidth=1.5;
    ctx.beginPath();ctx.moveTo(pcx+pw/2+1,pcy);ctx.lineTo(bx-6,pcy);ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle=WARM;ctx.beginPath();ctx.moveTo(bx,pcy);ctx.lineTo(bx-7,pcy-3.5);ctx.lineTo(bx-7,pcy+3.5);ctx.closePath();ctx.fill();
    for(b=0;b<2;b++){var ff=(time/0.25+b/2)%1;ctx.beginPath();ctx.arc(pcx+pw/2+(bx-pcx-pw/2-6)*ff,pcy,2.4,0,6.2832);ctx.fill();}
    ctx.globalAlpha=1;
  }

  // samples row
  var rx=0.36*W,rw=0.61*W,cw=rw/5,cy0=0.575*H,chh=0.19*H,busY=0.55*H;
  var s,S2=Math.min(cw*0.28,chh*0.24);
  if(minisA>0){
    var paths=[];
    for(s=0;s<5;s++){
      var mx=rx+cw*(s+0.5);
      paths.push([[pcx,pcy+ph/2],[pcx,busY],[mx,busY],[mx,cy0-1]]);
    }
    ctx.globalAlpha=busA*0.9;ctx.setLineDash([4,3]);ctx.lineDashOffset=-time*30;
    ctx.strokeStyle=WARM;ctx.lineWidth=1.3;
    for(s=0;s<5;s++){
      var pp=paths[s];ctx.beginPath();ctx.moveTo(pp[0][0],pp[0][1]);
      var q2;for(q2=1;q2<4;q2++)ctx.lineTo(pp[q2][0],pp[q2][1]);ctx.stroke();
    }
    ctx.setLineDash([]);ctx.fillStyle=WARM;
    for(s=0;s<5;s++){
      for(b=0;b<2;b++){var pt=pathPt(paths[s],(time/0.7+b/2)%1);ctx.beginPath();ctx.arc(pt[0],pt[1],2.2,0,6.2832);ctx.fill();}
    }
    ctx.globalAlpha=1;
    for(s=0;s<5;s++){
      var mcx=rx+cw*(s+0.5);
      ctx.globalAlpha=minisA;ctx.strokeStyle=GUIDE;ctx.lineWidth=1;
      ctx.strokeRect(rx+cw*s+2,cy0,cw-4,chh);ctx.globalAlpha=1;
      cloud(ctx,mcx,cy0+chh/2,S2,sigS,stepS,s,time*0.5+s*0.5,minisA,1.8,1);
    }
    ctx.textAlign='center';
    txt('samples x(1) … x(5) from the same c',rx+rw/2,0.815*H,SEC,minisA,rw);
  }

  // counters
  ctx.textAlign='left';
  var calls=t<4.6?0:(t<9.2?stepMain:(t<12.6?stepS*5:1000));
  if(t>=8.4&&t<9.2)calls=200;
  txt('trunk calls: 1',rx,0.875*H,BLUE,1,rw,true);
  txt('denoiser calls: 200 × samples',rx,0.925*H,WARM,1,rw,true);
  txt('so far: '+calls+' denoiser calls',rx,0.975*H,SEC,1,rw);

  // loop fade
  var fa=t>13.5?(t-13.5)/0.5:(t<0.35?1-t/0.35:0);
  if(fa>0){ctx.globalAlpha=cl(fa);ctx.fillStyle='#ffffff';ctx.fillRect(0,0,W,H);ctx.globalAlpha=1;}
}};
